function O({registerIndicator:w,sourceValues:g,nulls:A}){w({id:"oa-jvoltyn",name:"Normalized Jurik Volatility (JVOLTYN)",category:"Volatility",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1,tooltip:"Number of bars used in the calculation"},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"jvoltyn",type:"line",title:"JVoltyN",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,y){const n=Math.max(1,Math.floor(Number(y.period)||10)),i=g(l,y.source??"close"),p=Math.sqrt(.5*(n-1)),s=Math.max(Math.log(p)/Math.log(2)+2,0),M=Math.max(s-2,.5),N=p*s,L=2/(Math.max(4*n,65)+1),k=1/(10+10*Math.min(Math.max(n-10,0),100)/100),F=Math.pow(s,1/M),d=new Array(l.length).fill(NaN),f=new Array(l.length).fill(NaN);let c=Number.isFinite(i[0])?i[0]:0,b=c,r=0,e=0;for(let t=0;t<l.length;t++){const o=i[t];if(!Number.isFinite(o))continue;const u=o-c,h=o-b,m=Math.max(Math.abs(u),Math.abs(h));f[t]=m;const v=t>=10?f[t-10]:NaN,J=Number.isFinite(v)?v:0;r=r+(m-J)*k,e=e+L*(r-e);let a=1;e>0&&(a=m/e,a=Math.min(Math.max(a,1),F));const x=Math.pow(N/(N+1),Math.sqrt(Math.pow(a,M)));c=u>0?o:o-x*u,b=h<0?o:o-x*h;const V=1/(1+Math.exp(-(a-1)*1.5));Number.isFinite(V)&&(d[t]=V)}return{jvoltyn:A(d)}}})}export{O as default};
